// Labels and small helpers shared by the screens of the three-week question flow.

// Reviews generated by the system when no student reviewed the question
export const REVIEW_TAG_LABELS = {
  missing_reviewer: 'Chýbajúci recenzent',
  reviewer_no_response: 'Recenzent neodpovedal'
};

// The teacher's final decision on a published question
export const TEACHER_STATUS = {
  pending: { label: 'Čaká na posúdenie', color: 'default' },
  approved: { label: 'Schválená učiteľom', color: 'primary' },
  rejected: { label: 'Zamietnutá učiteľom', color: 'warning' },
  abuse: { label: 'Zamietnutá ako zneužitie', color: 'error' }
};

export const fullName = (person) =>
  person ? [person.name, person.surname].filter(Boolean).join(' ') || 'N/A' : 'N/A';

/** The teacher's decision, also for older records that only have validated_by_teacher. */
export const teacherStatusOf = (question) =>
  question.teacher_status && question.teacher_status !== 'pending'
    ? question.teacher_status
    : question.validated_by_teacher
      ? 'approved'
      : 'pending';
